        backgroundColor: "#000",
        color: "#fff",
        minHeight: "100vh",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <h1 style={{ fontSize: "2rem", margin: "1rem" }}>
        NodeLex v2.0 - Lenguajes Formales
      </h1>
      <Main />
    </div>
  );
}

export default App;
